// generated by tcacomp — deterministic output; do not edit
#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T QkScoreCombine0(T p0, T p1) {
  return (p0 + p1);
}

// QkScore: launch 128 CTAs x 1024 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 128 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(1024) QkScore(uint32_t H, uint32_t D, uint32_t N, const float* __restrict__ q, const float* __restrict__ kk, float* __restrict__ out, float scale) {
  tca::rt::TensorView<const float, 2u> q_v(q, H, D);
  tca::rt::TensorView<const float, 2u> kk_v(kk, N, D);
  tca::rt::TensorView<float, 2u> out_v(out, H, N);
  // dynamic SMEM pool (128 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];
  tca::rt::Frag<float, 1u, 8u> tca_f0;

  tca::rt::KernelInfo kinfo;
  // LNT #0: H=CTA(T=32,LoC=128) N=sequential(T=256,LoC=1) D=thread/warp(T=256,LoC=32) dim=thread/warp(LoC=1024) dim=sequential(LoC=1) D=sequential(T=256,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 128u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 128u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 32u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 32u);
    auto c0 = 0.0f;
    auto v0 = scale;
    auto c1 = 0u;
    auto v1 = H;
    auto v2 = N;
    auto c2 = 1u;
    auto v3 = D;
    auto v4 = grid_map0.index(0u);
    auto c3 = 32u;
    auto v5 = (v4 * c3);
    auto c4 = 256u;
    auto v6 = thread_map1.index(0u);
    auto v7 = (v6 * c4);
    auto v8 = thread_map1.lane_id();
    auto v9 = (v8 + c2);
    auto c5 = 8u;
    auto v10 = (v9 * c5);
    auto v11 = (v8 * c5);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, QkScoreCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 32u));
    // @H tile-between rounds — CTA, T=32, LoC=128 (map dim 0)
    for (auto H_it0 = tca::rt::CtaIterator(grid_map0, 0u, 128u, 0u, 4096u, v1); H_it0.Has(); H_it0.Next()) {
      auto v12 = (v5 + H_it0.Index());
      auto v13 = tca::rt::umin(v12, v1);
      auto v14 = (v1 - v13);
      auto v15 = tca::rt::umin(c3, v14);
      // @N tile-between rounds — sequential, T=256, LoC=1
      for (auto N_it1 = tca::rt::SeqIterator(0u, 256u, v2); N_it1.Has(); N_it1.Next()) {
        auto v16 = tca::rt::umin(N_it1.Index(), v2);
        auto v17 = (v2 - v16);
        auto v18 = tca::rt::umin(c4, v17);
        // @H walk — sequential, LoC=1
        for (auto H_it2 = tca::rt::SeqIterator(0u, 1u, v15); H_it2.Has(); H_it2.Next()) {
          auto v19 = (v12 + H_it2.Index());
          // @N walk — sequential, LoC=1
          for (auto N_it3 = tca::rt::SeqIterator(0u, 1u, v18); N_it3.Has(); N_it3.Next()) {
            // per-element bracket opens (argument-free; re-initializes from the construction-time init)
            reducer0.Init();
            // @D tile-between rounds — thread/warp, T=256, LoC=32 (map dim 0)
            for (auto D_it4 = tca::rt::ThrIterator(thread_map1, 0u, 32u, 0u, 8192u, v3); D_it4.Has(); D_it4.Next()) {
              auto v20 = (v7 + D_it4.Index());
              auto v21 = tca::rt::umin(v20, v3);
              auto v22 = (v3 - v21);
              auto v23 = tca::rt::umin(c4, v22);
              auto v24 = tca::rt::umin(v10, v23);
              auto v25 = (v20 + v11);
              // per-thread tile fill of q (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f0, tca::rt::TensorWindow(q_v, v19, v25));
              // @D inside walk (tile elements) — T=256
              for (auto D_it5 = tca::rt::SeqIterator((v8 * c5), 1u, v24); D_it5.Has(); D_it5.Next()) {
                auto v26 = (v20 + D_it5.Index());
                auto v27 = kk_v.Get((N_it1.Index() + N_it3.Index()), v26);
                auto v28 = (D_it5.Index() - v11);
                auto v29 = tca_f0.Get(v28);
                auto v30 = (v29 * v27);
                reducer0.Reduce(v30);
              }
            }
            // per-element combine — every participant receives the element's final value
            auto v31 = reducer0.Combine();
            auto v32 = (v31 * v0);
            // single-owner store — the element's owner thread writes (R2/R3)
            if (thread_map1.is_first_in_cta()) {
              out_v.Set(v32, (v12 + H_it2.Index()), (N_it1.Index() + N_it3.Index()));
            }
          }
        }
      }
    }
  }
}

}  // namespace

void QkScoreLaunch(const tca::Tensor<float, 2u>& q, const tca::Tensor<float, 2u>& kk, tca::Tensor<float, 2u>& out, float scale, cudaStream_t tca_stream) {
  const uint32_t H = q.Dim(0u);
  const uint32_t D = q.Dim(1u);
  const uint32_t N = kk.Dim(0u);
  TCA_REQUIRE(kk.Dim(1u) == D, "kk.Dim(1) must equal D (dim D)");
  TCA_REQUIRE(out.Dim(0u) == H, "out.Dim(0) must equal H (dim H)");
  TCA_REQUIRE(out.Dim(1u) == N, "out.Dim(1) must equal N (dim N)");
  tca::rt::ValidateLaunch(dim3(128u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, 512u);
  QkScore<<<dim3(128u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, tca_stream>>>(H, D, N, q.Data(), kk.Data(), out.Data(), scale);
  TCA_CUDA_CHECK(cudaGetLastError());
}
